import { type NextRequest, NextResponse } from "next/server";
import {
	prefersJsonError,
	prefersMarkdownError,
	shouldJsonError,
} from "@/lib/agent-404";
import {
	acceptFamily,
	classifyAgentSurface,
	isAiBotFamily,
	uaFamily,
} from "@/lib/agent-surface";
import { reportServerEvent } from "@/lib/analytics-server";
import { SITE } from "@/lib/constants";
import { notFoundExtensions, notFoundMarkdown } from "@/lib/not-found-body";
import { problemResponse } from "@/lib/problem";
import { hasMarkdownTwin } from "@/lib/page-markdown";
import {
	checkRateLimit,
	canonicalRoute,
	middlewareShouldMeter,
	rateLimitHeaders,
} from "@/lib/rate-limit";

// Agent content negotiation → the Markdown route (app/api/md). An agent can get
// raw Markdown three ways, all mapped here:
//   1. Accept: text/markdown            (content negotiation)
//   2. a `.md` suffix on the URL        (e.g. /docs/foundations/overview.md)
//   3. ?mode=agent                      (explicit machine-readable view)
// Browsers (Accept: text/html, no suffix, no flag) keep getting HTML.
function mdTarget(pathname: string): string | null {
	if (pathname === "/" || pathname === "/index.md") return "/api/md";
	// Strip a trailing `.md` so /docs/x.md and /docs/x resolve identically.
	const clean = pathname.endsWith(".md") ? pathname.slice(0, -3) : pathname;
	if (clean === "/docs" || clean === "/docs/") return "/api/md";
	if (clean.startsWith("/docs/")) {
		return `/api/md/${clean.slice("/docs/".length)}`;
	}
	// Named non-/docs pages with a Markdown twin (/developers.md, /yonyon.md).
	// The docs tell agents to append `.md` to a page URL; before this, doing that
	// outside /docs returned the HTML not-found page, which is what made the
	// "yonyon developer resources" query come back with nothing usable.
	const slug = clean.slice(1);
	if (hasMarkdownTwin(slug)) return `/api/page-md/${slug}`;
	return null;
}

// Whether a path is part of the API/agent surface that the rate-limit contract
// covers. HTML page views are deliberately excluded: metering them would let
// ordinary browsing (RSC prefetches, a fast reader) trip an abuse brake meant
// for API clients, and RateLimit headers on a marketing page are noise.
function isMeteredSurface(pathname: string): boolean {
	return (
		(pathname.startsWith("/api/") || classifyAgentSurface(pathname) !== null) &&
		middlewareShouldMeter(pathname)
	);
}

export function middleware(req: NextRequest) {
	const { pathname, searchParams } = req.nextUrl;
	const accept = req.headers.get("accept") ?? "";
	// Bounded property values shared by every branch below. See lib/agent-surface.
	const audience = {
		accept_family: acceptFamily(accept),
		ua_family: uaFamily(req.headers.get("user-agent")),
		method: req.method,
	};

	// 0) Rate-limit accounting for the whole API/agent surface.
	//
	// This has to happen in middleware, not in the handlers: the agent surfaces a
	// scanner actually probes first, /openapi.json, /llms.txt, /api/health, the
	// eight /.well-known/* cards, are `revalidate = false` handlers that execute
	// at BUILD time and are then served from the CDN, so a header computed inside
	// them would be frozen at one build-time value or absent entirely. That is why
	// the audit found the limits "documented in the OpenAPI spec, but not observed
	// on a live response": /api/search did emit them, every prerendered surface
	// did not. Middleware runs per request, so it can.
	//
	// Routes that meter themselves are skipped (see SELF_LIMITED_ROUTES), double
	// counting would silently halve the published ceiling.
	const metered = isMeteredSurface(pathname);
	const limit = metered ? checkRateLimit(req, canonicalRoute(pathname)) : null;
	const limitHeaders = limit ? rateLimitHeaders(limit) : {};

	if (limit?.limited) {
		return problemResponse(
			{
				type: `${SITE.domain}/api-policy`,
				title: "Too Many Requests",
				status: 429,
				detail: `Rate limit exceeded for ${pathname}. Retry after ${limit.resetSeconds}s; see ${SITE.domain}/api-policy for the published limits.`,
				instance: pathname,
			},
			{ ...limitHeaders, "Retry-After": String(limit.resetSeconds) },
		);
	}

	// 1) Markdown content negotiation → the Markdown route (only / and /docs/*).
	//
	// The fourth trigger is the User-Agent. GPTBot, ClaudeBot, PerplexityBot and
	// the rest send `Accept: */*` or `text/html` and none of them know the `.md`
	// convention, so all three explicit triggers above miss every one of them:
	// the surface built for LLM readers was reachable only by clients that
	// already knew it existed. uaFamily() has classified these UAs since the
	// telemetry work; this is the first time the classification decides anything.
	//
	// This makes one URL serve two bodies keyed on User-Agent, so
	// `Vary: Accept, Accept-Encoding, User-Agent` in next.config.mjs (and in the
	// Markdown handlers' own headers) is load-bearing, not decoration. Without
	// the User-Agent token a shared cache is free to hand a browser the copy it
	// stored for GPTBot, which is a worse bug than never serving bots Markdown.
	const isAiBot = isAiBotFamily(audience.ua_family);
	const wantsMarkdown =
		accept.includes("text/markdown") ||
		pathname.endsWith(".md") ||
		searchParams.get("mode") === "agent" ||
		isAiBot;

	if (wantsMarkdown) {
		const target = mdTarget(pathname);
		if (target) {
			const url = req.nextUrl.clone();
			url.pathname = target;
			url.search = ""; // drop ?mode=agent so it doesn't leak into the rewrite
			// Which of the three entry paths an agent actually used is only known
			// HERE — middleware is what decides the rewrite, and the rewritten
			// handler cannot tell them apart. Emitting it here avoids inventing a
			// middleware→handler header contract just to carry one property.
			reportServerEvent(req.headers, "agent:api-request", pathname, {
				...audience,
				surface: "md",
				trigger: accept.includes("text/markdown")
					? "accept-header"
					: pathname.endsWith(".md")
						? "dot-md-suffix"
						: searchParams.get("mode") === "agent"
							? "mode-agent-param"
							: "bot-ua",
			});
			const rewritten = NextResponse.rewrite(url);
			for (const [k, v] of Object.entries(limitHeaders)) {
				rewritten.headers.set(k, v);
			}
			return rewritten;
		}
	}

	// 2) Content-negotiated 404: an unknown path requested by a non-browser
	// client gets a structured RFC 9457 error instead of the HTML not-found page,
	// so agents parse the failure instead of scraping markup.
	if (shouldJsonError(req.method, pathname, accept)) {
		// The highest-signal event on this surface: it names the paths agents
		// expect and we do not serve, which is how SERVED_EXACT and the
		// next.config rewrite table should actually be grown.
		reportServerEvent(req.headers, "agent:not-found", pathname, {
			...audience,
			branch: "middleware-json-404",
		});
		// An agent that asked for Markdown gets Markdown, even for the failure.
		// A bare 404 status is only half the contract: the other half is telling
		// the client where to look next, in the media type it asked for. Both
		// representations are built from lib/not-found-body.ts, so the JSON and
		// Markdown answers list the same recovery hops.
		if (prefersMarkdownError(pathname, accept, searchParams.get("mode"))) {
			return new Response(notFoundMarkdown(pathname, SITE.domain), {
				status: 404,
				headers: {
					"Content-Type": "text/markdown; charset=utf-8",
					"Cache-Control": "public, max-age=0, must-revalidate",
					...limitHeaders,
				},
			});
		}
		return problemResponse(
			{
				type: `${SITE.domain}/docs/reference`,
				title: "Resource not found",
				status: 404,
				detail: `No resource at ${pathname}. Browse /docs, or see the API catalog at /.well-known/api-catalog. Send \`Accept: text/markdown\` for this guidance as Markdown.`,
				instance: pathname,
			},
			limitHeaders,
			notFoundExtensions(SITE.domain),
		);
	}

	// 3) Agent-surface reach. This is the ONLY place the eight prerendered
	// /.well-known/* handlers, /openapi.json and /llms.txt are observable at all:
	// they are `revalidate = false` + zero-arg GET(), so they execute at build
	// time and are served from the CDN, and any capture() inside them would run
	// once, ever. Double-gated to keep volume honest — a non-HTML Accept AND a
	// path that is actually an agent surface, so browser page loads, RSC
	// payloads, static assets and the PostHog proxy emit nothing.
	//
	// The third gate is `client=dialog`. A non-HTML Accept does NOT mean "agent":
	// browser fetch() and navigator.sendBeacon both send `Accept: */*`, so our
	// own CMD-K dialog calling /api/search looked exactly like an agent. fumadocs
	// debounces that fetch at 100ms, which meant one event per settled keystroke.
	// The dialog now tags its own requests; anything else hitting /api/search is
	// a genuine caller of the documented endpoint and still counts.
	const surface = classifyAgentSurface(pathname);
	const isOwnClient = req.nextUrl.searchParams.get("client") === "dialog";
	if (surface && prefersJsonError(accept) && !isOwnClient) {
		reportServerEvent(req.headers, "agent:api-request", pathname, {
			...audience,
			surface,
		});
	}

	const res = NextResponse.next();
	for (const [k, v] of Object.entries(limitHeaders)) {
		res.headers.set(k, v);
	}
	return res;
}

export const config = {
	// Run on everything except Next internals so the 404 negotiation can see any
	// unknown path; the markdown branch still only acts on / and /docs/*.
	matcher: ["/((?!_next/static|_next/image).*)"],
};
